INSERT INTO herbal_knowledge (herb_name, part_used, taste, properties) VALUES
    ('สารส้ม', 'ผลึก', 'ฝาดเปรี้ยว', 'สมานทั้งภายนอกภายใน แก้ระดูขาว แก้หนองใน ขับปัสสาวะ ขับนิ่ว แก้ปอดอักเสบ ขับฟอกล้างโลหิตระดู แก้รำมะนาด เหงือกเป็นแผลบวม ทำให้ฟันมั่นคง สมานแผลห้ามเลือด แก้เม็ดผื่นคัน แก้ชันนะตุพุพอง'),
    ('ดินประสิว', 'ผง', 'เค็มปร่า', 'ขับลมที่คั่งค้างตามเส้น ทำให้เส้นหย่อน ถอนพิษ ขับปัสสาวะ อาหารไม่ย่อย ใช้ภายนอกสำหรับทาแก้คันตามผิวหนัง จี้หูด'),
    ('ขิง', 'เหง้า', 'เผ็ดร้อน', 'แก้ท้องอืด จุกเสียด แน่นเฟ้อ คลื่นไส้อาเจียน แก้หอบไอ ขับเสมหะ แก้บิด เจริญอากาศธาตุ'),
    ('เกลือสินเธาว์', 'ผลึก', 'เค็ม', 'ทำลายพรรดึก แก้ระส่ำระสาย แก้สมุฏฐานตรีโทษ แก้นิ่ว ขับพยาธิภายในท้องล้างเมือกมันภายใน'),
    ('ข้าวเย็นเหนือ', 'หัว/เหง้า', 'มันกร่อยหวานเล็กน้อย', 'แก้ประดง มะเร็งคุดทะราด แก้ร้อนในกระหายน้ำ แก้น้ำเหลืองเสีย ฆ่าเชื้อหนอง แก้เส้นเอ็นพิการ แก้กามโรค เข้าข้อออกดอก ฝีแผล เน่าเปื่อยพุพอง ทำให้แผลฝียุบแห้ง แก้เม็ดผื่นคัน ดับพิษในกระดูก แก้ปัสสาวะ'),
    ('ข้าวเย็นใต้', 'หัว/เหง้า', 'มันกร่อย หวานเล็กน้อย', 'แก้ประดง มะเร็งคุดทะราด แก้ร้อนในกระหายน้ำ แก้น้ำเหลืองเสีย ฆ่าเชื้อหนอง แก้เส้นเอ็นพิการ แก้กามโรค เข้าข้อออกดอก ฝีแผล เน่าเปื่อยพุพอง ทำให้แผลฝียุบแห้ง แก้เม็ดผื่นคัน ดับพิษในกระดูก แก้ปัสสาวะ'),
    ('โคกกระสุน', 'เถา/ทั้งต้น', 'ขมเล็กน้อย', 'ขับปัสสาวะ แก้กษัย แก้ปัสสาวะพิการ ใช้แก้พิษไข้ ทั้งภายในและภายนอก บำรุงหัวใจ แก้พิษฝีที่มีอาการอักเสบ อาการปวดบวม'),
    ('จันทน์แดง', 'แก่น', 'เผ็ดหวาน', 'บำรุงประสาท บำรุงเนื้อหนังให้สดชื่น แก้ร้อนในกระหายน้ำ แก้ตับปอด และดีพิการ แก้เหงื่อตกหนัก ขับพยาธิ'),
    ('จันทน์ขาว', 'แก่น', 'เผ็ดร้อนหอมขมเล็กน้อย', 'แก้ลม และดีพิการ ขับเสมหะ แก้นิ่ว ขับระดูขาว แก้ท้องขึ้น ในเด็ก'),
    ('เทียนขาว', NULL, 'ขื่นขมฝาด', 'บำรุงโลหิตสตรี แก้ปอดพิการ ขับหนอง'),
    ('ฝาง', 'แก่น', 'เผ็ดร้อนขม', 'แก้ปถวีธาตุพิการ แก้ท้องร่วง ขับลมในลำไส้ แก้หืดไอ แก้ลมวิงเวียน ช่วยเจริญอาหาร'),
    ('ดีปลี', 'ผล', 'เผ็ดร้อนขม', 'ขับลม ช่วยเจริญอาหาร แก้โรคในอก แก้ลมทั้งปวง เจริญไฟธาตุและแก้เสมหะ'),
    ('พริกไทย', 'เมล็ด', 'เผ็ด', 'ขับลม ช่วยเจริญอาหาร แก้โรคในอก แก้ลมทั้งปวง เจริญไฟธาตุและแก้เสมหะ'),
    ('มะนาว', 'น้ำ', 'เปรี้ยว', 'ขับปัสสาวะ แก้กษัย แก้ปัสสาวะพิการ'),
    ('ลำเจียก', 'ราก', 'จืดหวานเล็กน้อย', 'ขับปัสสาวะ แก้นิ่ว แก้น้ำปัสสาวะพิการ'),
    ('เบี้ยจั่นเผา', 'เถ้า', 'เค็มกร่อย', 'ขับนิ่วในไต ขับปัสสาวะ'),
    ('อ้อย', 'น้ำ', 'หวานเย็น', 'กินเจริญเสมหะดี แก้อาเจียน แก้กระหายน้ำ'),
    ('สน', 'แก่น', 'ขมเผ็ด', 'แก้ไข้อันบังเกิดแต่เสมหะแลกระจายเสียซึ่งลม'),
    ('เจตมูลเพลิงแดง', 'ราก', 'เผ็ดร้อน', 'เป็นยาบำรุงไฟธาตุ กระตุ้นลำไส้และกระเพาะอาหารให้ย่อยอาหารดีขึ้น และขับน้ำย่อยอาหาร ทำให้ร่างกายอบอุ่น'),
    ('เทียนแดง', 'เมล็ด', 'เผ็ดร้อน', '- แก้เสมหะ แก้ลม แก้น้ำดีพิการ แก้ลมเสียดแทงสองราวข้าง แก้คลื่นไส้อาเจียน ขับน้ำนม แก้ลักปิดลักเปิด ฟอกโลหิต'),
    ('หญ้าแพรก', 'ราก/ทั้งต้น', 'ขมเย็น', 'แก้พิษเจ็บปวด แก้อักเสบ แก้สตรีตกโลหิตมากเกินไป แก้ร้อนในกระหายน้ำ แก้ไข้พิษไข้กาฬ ไข้หัด สุกใส ดำ แดง'),
    ('รากหญ้าคา', 'ราก', 'หวานจืดเย็น', 'ขับปัสสาวะ แก้น้ำปัสสาวะขัด แก้ปัสสาวะเป็นเลือด ดับพิษไข้ แก้ไข้ตัวร้อน ดับพิษกาฬ แก้ร้อนในกระหายน้ำ ห้ามเลือดกำเดาไหล แก้บวมน้ำ บำรุงไต และลดความร้อนสะสมในร่างกาย'),
    ('ปูนใส', 'น้ำ', 'ฝาดปร่า', 'คุมธาตุ แก้ท้องร่วง สมานลำไส้ แก้บิดมูกเลือด แก้อาการท้องเสีย ท้องเดิน กัดเสมหะและเมือกมัน ล้างและสมานแผลเปื่อย แผลพุพอง ห้ามเลือดและดับพิษร้อนภายนอก แก้อาการแสบร้อนและลดกรดในกระเพาะอาหาร'),
    ('สับปะรด', 'เหง้า', 'หวานเย็นเปรี้ยว', 'ชำระปัสสาวะ แก้ขัดเบา แก้นิ่ว แก้หนองใน'),
    ('หญ้างวงช้าง', 'ราก/ทั้งต้น', 'เย็น', 'แก้พิษตานซาง ลดไข้ในเด็ก แก้กระหายน้ำ ละลายก้อนนิ่ว แก้โรคตา'),
    ('บานไม่รู้โรยขาว', 'ราก', 'เย็นขื่น', 'ขับปัสสาวะ แก้หนองใน ขับระดูขาว แก้กามโรค แก้กษัย'),
    ('มะละกอ', 'ราก', 'ขื่นฉุนเอียน', 'แก้ปัสสาวะอักเสบ แก้หนองใน ขับปัสสาวะ เจริญอาหาร แก้ มุตกิตระดูขาว บำรุงน้ำนม'),
    ('มะขาม', 'ใบ', 'เปรี้ยวฝาด', 'ขับเสมหะในลำไส้ แก้บิด แก้ไอ ต้มน้ำโกรกศีรษะเด็กเวลาเช้ามืดแก้หวัดขัดจมูก'),
    ('ส้มป่อย', 'ใบ', 'เปรี้ยวฝาดเล็กน้อย', 'ถ่ายเสมหะ ล้างเมือกมันในลำไส้ แก้บิด ฟอกล้างโลหิตระดู ประคบให้เส้นเอ็นอ่อน'),
    ('มะนาว', 'ใบ', 'ปร่า', 'เป็นยากัดฟอกโลหิต ฟอกโลหิตระดู และใช้แก้ปวดศีรษะ ปวดท้อง แก้ไอ เจริญอาหาร ขับลม'),
    ('หอมแดง', 'หัว', 'หวานเค็ม', 'แก้ไข้หวัดแลไข้อันผูกเป็นเจ้าเรือนแลแก้ไข้'),
    ('กรักขี', 'แก่น', 'เผ็ดฝาด', 'บำรุงธาตุ บำรุงโลหิต ขับเสมหะ แก้เลือดออกตามไรฟัน แก้คุดทะลาด แก้บิดมูกเลือด'),
    ('ประดู่', 'แก่น', 'ขมฝาด', 'แก้เสมหะ โลหิตและกำเดา แก้ไข้ บำรุงโลหิต'),
    ('ปรู', 'แก่น', 'จืดเฝื่อน', 'แก้น้ำเหลือง บำรุงกำลัง'),
    ('โกฐก้านพร้าว', NULL, 'เย็น', 'แก้ไข้ แก้หอบ แก้สะอึก แก้เสมหะเป็นพิษ'),
    ('มะตูม', 'ผล', 'ร้อนปร่าขื่น', 'แก้ธาตุพิการ แก้ท้องเสีย แก้บิด แก้โรคกระเพาะอาหาร ทำให้เจริญอาหาร ขับลม บำรุงกำลัง'),
    ('ขัดมอน', 'ราก', 'เผ็ด', 'แก้พิษไข้ ไข้กาฬ แก้ไข้หัด สุกใส ดำแดง ฝีดาษ แก้ร้อนใน แก้ เยื่อหุ้มสมองอักเสบ แก้ปวดมดลูก'),
    ('แห้วหมู', 'หัว', 'ซ่าร้อนเผ็ด', 'ขับลมในลำไส้ แก้ปวดประจำเดือน แก้ประจำเดือนผิดปกติ บำรุงธาตุ เจริญอาหาร แก้ท้องอืดเฟ้อ บำรุงกำลัง บำรุงครรภ์ เป็นยาบำรุงหัวใจ ขับเหงื่อ ขับระดูขับปัสสาวะ สรรพคุณแก้ไข้เป็นยาฝาดสมาน สงบประสาท'),
    ('กระดอม', 'ลูก', 'ขมจัด', 'บำรุงน้ำดี แก้ดีแห้ง ดีฝ่อ ดีเดือด เจริญอาหาร ทำให้โลหิตเย็น บำรุงมดลูกหลังแท้งหรือคลอดบุตร แก้มดลูกอักเสบ แก้ไข้'),
    ('บอระเพ็ด', 'เถา', 'ขมมัน', 'แก้พิษฝีดาษ แก้ไข้เหนือ ไข้พิษ แก้ฝีกาฬ โรคแทรกของไข้ทรพิษ แก้ไข้ทุกชนิด บำรุงกำลัง เจริญไฟธาตุ แก้ร้อนใน แก้สะอึก'),
    ('ขมิ้นอ้อย', 'เหง้า', 'ฝาดเฝื่อน', 'แก้ครั่นเนื้อครั่นตัว สมานลำไส้ แก้ระดูขาว ขับปัสสาวะ'),
    ('บัวหลวง', 'เกสร', 'ฝาดหอม', 'บำรุงหัวใจ ตับพิษร้อน ทำให้จิตใจชุ่มชื่น บำรุงครรภ์ แก้ร้อนใน กระหายน้ำ บำรุงปอด บำรุงตับ'),
    ('บุนนาค', 'ดอก', 'ขมหอมเย็น', 'บำรุงดวงจิตให้แช่มชื่น แก้ไข้กาฬ แก้ร้อนใน ตับกระหาย บำรุงโลหิต บำรุงหัวใจ แก้ลมกองละเอียด แก้วิงเวียนหน้ามืดตาลาย'),
    ('คำไทย', 'ดอก', 'หวาน', NULL),
    ('สะค้าน', 'เถา', 'เผ็ดร้อน', 'บำรุงธาตุ แก้ลมอันบังเกิดจากกองธาตุ ขับลมในลำไส้ ทำให้ผายลมและเรอ แก้แน่น แก้จุกเสียด'),
    ('ช้าพลู', 'ราก', 'เผ็ดเล็กน้อย', 'แก้คูถเสมหะ แก้อุระเสมหะ ปรุงเป็นยาแก้ธาตุพิการ บำรุงธาตุ'),
    ('ขิงแห้ง', 'เหง้า', 'หวานเผ็ดร้อน', 'เจริญอากาศธาตุ และบำรุงธาตุไฟให้ทำงานเป็นปกติ ขับลมในลำไส้ กระเพาะอาหาร แก้แน่น จุกเสียด ท้องอืด ท้องเฟ้อ แก้อาการคลื่นไส้ อาเจียน แก้ลมพานไส้ ขับเหงื่อ ขับเสมหะ บรรเทาอาการไอและระงับหวัดลมหนาว'),
    ('กาบหอยเผา', 'เถ้า', 'เค็มกร่อย', 'ขับนิ่วในไต ขับปัสสาวะ'),
    ('พิลังกาสา', 'ลูก', 'ฝาดสุขุม', 'แก้ท้องเสีย'),
    ('ช้าพลู', 'ผล', 'เผ็ดร้อน', 'แก้เสมหะที่คอ ทำให้เสมหะแห้ง ขับลมในลำไส้ ช่วยย่อยอาหาร'),
    ('จิงจ้อน้อ', 'ราก', 'ขมขื่นเย็น', 'ขับบปัสสาวะ แก้น้ำปัสสาวะขัดหรือพิการ ดับพิษไข้ ถอนพิษร้อน ดับพิษตานซาง ขับเสมหะ แก้ร้อนในกระหายน้ำ แก้ฟกบวม ดับพิษฝีภายในและภายนอก'),
    ('หมอน้อย', 'ราก', 'ขมเอียน', 'ขับปัสสาวะ ดับพิษไข้ ดับพิษร้อน แก้ไอ ระงับหอบ ขับเสมหะและบรรเทาการอักเสบในลำคอ แก้บิด ท้องเสีย แก้ปวดมวนในท้อง แก้ริดสีดวงทวาร สมานแผล และช่วยลดความอยากบุหรี่'),
    ('พิลังกาสา', 'ราก', 'เมา', 'แก้กามโรค และหนองใน'),
    ('ช้าเลือดตัวผู้', NULL, 'เฝื่อนฝาดขม', 'โลหิตระดูสตรี ฟอกโลหิตระดูที่เน่าร้ายให้เป็นปกติ ขับน้ำคาวปลาในสตรีหลังคลอดบุตร แก้มุตกิตระดูขาว อาการตกขาวผิดปกติ บำรุงโลหิต บรรเทาอาการปวดเมื่อยตามร่างกายและเส้นเอ็น'),
    ('กำลังหนุมาน', NULL, 'ขมมัน', 'แก้น้ำดีพิการ นอนสะดุ้ง ผวา หลับๆตื่นๆ ร้อนหน้า น้ำตาไหล บำรุงกำลัง'),
    ('มะแว้งต้น', 'ราก', 'เปรี้ยวขื่นขม', 'แก้เสมหะ แก้ไอ แก้น้ำลายเหนียว'),
    ('มะแว้งเครือ', 'ราก', 'ขมขื่นเปรี้ยว', 'แก้ไอ แก้เจ็บคอ ขับเสมหะ ขับปัสสาวะ เจริญอาหาร แก้เบาหวาน'),
    ('เอื้องใหญ่', 'ราก', 'จืดขื่นเย็น', 'ขับปัสสาวะ ขับนิ่ว แก้น้ำเบาพิการ แก้ร้อนใน กระหายน้ำ ดับพิษไข้กาฬและไข้พิษ แก้โรคหนองใน และอาการอักเสบในทางเดินปัสสาวะ แก้อาการบวมน้ำ บำรุงและแก้น้ำเหลืองเสีย'),
    ('ชะลูด', 'เปลือก', 'เผ็ดเล็กน้อย', 'แก้คูถเสมหะ แก้อุระเสมหะ ยาแก้ธาตุพิการ บำรุงธาตุ'),
    ('บุนนาค', 'ราก', 'ขมหอมเย็น', 'บำรุงดวงจิตให้แช่มชื่น แก้ไข้กาฬ แก้ร้อนใน ตับกระหาย บำรุงโลหิต บำรุงหัวใจ แก้ลมกองละเอียด แก้วิงเวียนหน้ามืดตาลาย'),
    ('โหรามิคสิงคี', 'ราก', 'เมาเย็น', 'ถอนพิษ แก้'),
